export type IconName = keyof typeof STROKE | keyof typeof FILLED;

interface Props {
  name: IconName | string;
  size?: number;
  stroke?: number;
  color?: string;
  className?: string;
  style?: CSSProperties;
  title?: string;
}

export function Icon({ name, size = 20, stroke = 1.8, color = 'currentColor', className, style, title }: Props) {
  const filled = FILLED[name];
  const a11y = title ? { role: 'img', 'aria-label': title } : { 'aria-hidden': true as const };
  if (filled) {
    return (
      <svg width={size} height={size} viewBox={filled.vb} className={className} style={style} {...a11y}>
        <path d={filled.d} fill={color} />
      </svg>
    );
  }
  const paths = STROKE[name];
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth={stroke}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      style={style}
      {...a11y}
    >
      {paths}
    </svg>
  );
}
